import 'package:cloud_firestore/cloud_firestore.dart'; import 'package:flutter/material.dart'; class ProductsAdminPage extends StatelessWidget{const ProductsAdminPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Kelola Produk')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text(x['title']??'Produk'),subtitle:Text('Rp '+(x['price']??0).toString()),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>d.reference.update({'status':'inactive'})));}).toList());}));}